mapper.select:
SELECT p.id, p.product_name, p.product_image, cc.child_category_name, sp.store_price, sp.store_stock
FROM store_products sp
INNER JOIN products p ON sp.product_id = p.id
INNER JOIN child_categories cc ON cc.id = p.child_category_id
INNER JOIN sub_categories sc ON cc.sub_category_id = sc.id
INNER JOIN main_categories mc ON sc.main_category_id = mc.id
WHERE sp.store_id = #{storeId}
AND p.product_name LIKE CONCAT('%', #{productName}, '%')
AND mc.id = #{mainCategoryId}
AND sc.id = #{subCategoryId}
AND cc.id = #{childCategoryId}
ORDER BY p.id
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(p.id)
FROM store_products sp
INNER JOIN products p ON sp.product_id = p.id
INNER JOIN child_categories cc ON cc.id = p.child_category_id
INNER JOIN sub_categories sc ON cc.sub_category_id = sc.id
INNER JOIN main_categories mc ON sc.main_category_id = mc.id
WHERE sp.store_id = #{storeId}
AND p.product_name LIKE CONCAT('%', #{productName}, '%')
AND mc.id = #{mainCategoryId}
AND sc.id = #{subCategoryId}
AND cc.id = #{childCategoryId}

SELECT p.id, p.product_image, p.product_name, p.purchase_cost,sp.store_stock

FROM products p

INNER JOIN store_products sp
ON p.id = sp.product_id

WHERE sp.store_id = #{storeId}
AND sp.product_id = #{productId}

mapper.update:
UPDATE store_products 
SET store_stock = store_stock + #{orderNumber} 
WHERE store_id = #{storeId} 
AND product_id = #{productId}
